Use lesson 3’s folder. Replace server.js with this version, which only tells whether it got the password (without showing it):
const express = require("express");
const app = express();
const hasPassword = Boolean(process.env.DB_PASSWORD);
app.get("/", (req, res) => res.send("Hello from the lunchbox kitchen! Password received: " + hasPassword + "\n"));
app.listen(3000, () => console.log("listening on port 3000"));
